parameters.jsonBody:
={
    "phone": "{{ 
  (() => {
    let phone = String($json.whatsapp || "").replace(/\D/g, "");

    // Remove prefixo internacional com 00, ex: 005511989342471
    if (phone.startsWith("00")) {
      phone = phone.slice(2);
    }

    // Se vier com 0 antes do DDD, ex: 011989342471
    if (phone.startsWith("0") && phone.length >= 11) {
      phone = phone.slice(1);
    }

    // Se já vier com 55, mantém
    if (phone.startsWith("55")) {
      return phone;
    }

    // Se vier DDD + número celular com 9 dígitos, ex: 11989342471
    if (phone.length === 11) {
      return "55" + phone;
    }

    // Se vier DDD + número com 8 dígitos, NÃO adiciona o 9
    // Ex: 1188888888 vira 551188888888
    if (phone.length === 10) {
      return "55" + phone;
    }

    return phone;
  })()
}}",
    "ultimo_contato": "{{ $now.toFormat('yyyy-MM-dd') }}",
    "fup": "{{ $now.plus({ days: 2 }).toFormat('yyyy-MM-dd') }}",
    "status_plano_acao": "ptentativaderreativaçãor",
    "midia": "14",
    "dono_do_lead": "29"
  }

parameters.list:
={{
(raw => {
  let t = (raw || "").toString().replace(/\s+/g, "").replace(/\D/g, "");
  t = t.replace(/^0+/, "");

  if (t.length === 8) {
    // número sem DDD
    t = "11" + "9" + t;
  } else if (t.length === 9) {
    // celular sem DDD
    t = "11" + t;
  } else if (t.length === 10) {
    // DDD + telefone sem 9
    t = t.replace(/^(\d{2})(\d{8})$/, "$19$2");
  } else if (t.length === 11) {
    // DDD + celular
    t = "55" + t;
  } else if (t.length === 12) {
    // 55 + DDD + telefone sem 9
    t = t.slice(0, 4) + "9" + t.slice(4);
  } else if (t.length > 13) {
    // mantém apenas os últimos 13 dígitos
    t = t.slice(-13);
  }

  return t;
})($('Buscar Mailing Criado').first().json.whatsapp)
}}_mem_agent_FINAMOB_SDR

